document.documentElement.classList.add('js');
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let paused=false,scheduled=false,lastChapter=-1;
const hero=$('.hero-track'),heroContent=$('.hero-content'),heroArt=$('.hero-art'),science=$('.science-track'),molecule=$('.molecule'),progress=$('.read-progress');
const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));
function render(){scheduled=false;const y=scrollY;progress.style.transform=`scaleX(${clamp(y/(document.documentElement.scrollHeight-innerHeight))})`;if(!reduced.matches&&!paused){const h=hero.getBoundingClientRect();const p=clamp(-h.top/(hero.offsetHeight-innerHeight));heroArt.style.transform=`translate3d(${p*3}%,${p*5}%,0) scale(${1+p*.12})`;heroContent.style.transform=`translate3d(0,${-p*65}px,0)`;heroContent.style.opacity=1-p*.75;const r=science.getBoundingClientRect();const start=parseFloat(getComputedStyle($('.science-sticky')).top);const s=clamp((start-r.top)/(science.offsetHeight-innerHeight+start));molecule.style.transform=`rotateX(${s*35-10}deg) rotateY(${s*130-20}deg) rotateZ(${s*35-15}deg)`;setChapter(Math.min(2,Math.floor(s*3)));}}
function setChapter(n){if(n===lastChapter)return;lastChapter=n;$$('.chapter').forEach((e,i)=>{e.classList.toggle('active',i===n);e.setAttribute('aria-hidden',String(!reduced.matches&&i!==n));});$$('.chapter-nav button').forEach((e,i)=>{e.classList.toggle('active',i===n);e.setAttribute('aria-pressed',String(i===n));});$('.chapter-count').textContent=`0${n+1} — 03`;}
function schedule(){if(!scheduled){scheduled=true;requestAnimationFrame(render)}}
addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);reduced.addEventListener('change',()=>{lastChapter=-1;setChapter(0);schedule()});
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});$$('.reveal').forEach(e=>observer.observe(e));
$('#motion-toggle').addEventListener('click',e=>{paused=!paused;document.body.classList.toggle('motion-paused',paused);e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.textContent=paused?'▶ Resume motion':'Ⅱ Pause motion';if(!paused)schedule()});
$$('.chapter-nav button').forEach((button,i)=>button.addEventListener('click',()=>{if(paused){setChapter(i);return}const top=scrollY+science.getBoundingClientRect().top;const inset=parseFloat(getComputedStyle($('.science-sticky')).top);scrollTo({top:top-inset+(science.offsetHeight-innerHeight+inset)*((i+.15)/3),behavior:reduced.matches?'instant':'smooth'})}));
const menu=$('.menu-toggle'),nav=$('#navigation');function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.textContent='☰'}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰'});$$('nav a').forEach(a=>a.addEventListener('click',closeMenu));addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus()}});
$('#category').addEventListener('change',e=>$('#fee').textContent=new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(e.target.value)));
$('#year').textContent=new Date().getFullYear();setChapter(0);render();
